\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
Let $L$ be an ample line bundle on a complex manifold $X$. Is $K_X\otimes L^m$ globally generated for $m\geq\dim X+1$ and very ample for $m\geq\dim X+2$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2014/10}{[S2]}.

\subsection{Short English statement}
Let $L$ be an ample line bundle on a complex manifold $X$. Is $K_X\otimes L^m$ globally generated for $m\geq\dim X+1$ and very ample for $m\geq\dim X+2$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30002536 (OWR-12870-009). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
